import{_ as s,l,o as e,c as d,v as o,p as c,x as t,d as i,i as n,S as p}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"存储缓冲与 load 绕过","description":"","frontmatter":{"title":"存储缓冲与 load 绕过","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/store-buffer.md","filePath":"cs/store-buffer.md","lastUpdated":1789023840000}'),h={name:"cs/store-buffer.md"};function E(A,a,f,B,_,u){const r=l("Mermaid");return e(),d("div",null,[a[1]||(a[1]=o('<h1 id="存储缓冲与-load-绕过" tabindex="-1">存储缓冲与 load 绕过 <a class="header-anchor" href="#存储缓冲与-load-绕过" aria-label="Permalink to &quot;存储缓冲与 load 绕过&quot;">​</a></h1><div class="epigraph"><p>store 在提交前不能让 cache 对外可见，但后一条 load 同一地址又必须读到这条 store 的数据。</p><footer>—— 据 Hennessy and Patterson, Computer Architecture: A Quantitative Approach 整理</footer></div><p><a href="/cs/rs-cdb">上一课</a>让 ALU 结果经 CDB 唤醒。<a href="/cs/ooo-rob">乱序与 ROB</a> 规定未提交 store 不得进一致性世界。<a href="/cs/write-back-allocate">写回与写分配</a>的写缓冲是已提交写与 DRAM 之间的队列，对象不同。本课不重讲标签匹配。缺口是核内 store buffer：按程序序托住已执行未提交（或已提交未退休到 cache）的写，以及 load 对它的地址匹配与绕过。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>sw x1, 0(x2)</code> 后 <code>lw x3, 0(x2)</code>。store 可能还在 ROB 里，cache 仍是旧行。若 load 去 cache，ISA 的 RAW 被打破。若等到 store 提交，独立 load 也全停。缺口不是再加一条 CDB，而是<strong>按地址在 store 队列里搜，命中则把数据转发给 load</strong>（store-to-load forwarding）。</p><p>地址尚未算完的年轻 store 挡在前面时，load 不能盲目绕过——可能别名。实现要么等地址，要么预测「不冲突」错了再冲刷。</p><p><span class="marginnote">这是核内的 RAW，不是 MESI。别的核要等 store 提交并走一致性事务才看得到。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>store 在地址与数据就绪后写入缓冲项，与 ROB 项关联。提交时该项才有资格发 cache/MESI。load 执行时：用有效地址查更年长的 store 缓冲；完全重叠则转发；部分重叠或地址未知则停或按预测走。</p>',9)),(e(),c(p,null,{default:t(()=>[n(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20ST%5B%22store%20%E5%85%A5%E7%BC%93%E5%86%B2%22%5D%20--%3E%20COM%5B%22ROB%20%E5%A4%B4%E6%8F%90%E4%BA%A4%E6%89%8D%E5%86%99%20cache%22%5D%0A%20%20LD%5B%22load%20%E6%9F%A5%E7%BC%93%E5%86%B2%22%5D%20--%3E%20FWD%5B%22%E5%90%8C%E5%9C%B0%E5%9D%80%EF%BC%9A%E7%BB%95%E8%BF%87%22%5D%0A%20%20LD%20--%3E%20CACHE%5B%22%E6%97%A0%E5%8C%B9%E9%85%8D%EF%BC%9A%E6%9F%A5%20cache%22%5D%0A%20%20COM%20--%3E%20COH%5B%22%E6%AD%A4%E5%90%8E%E6%89%8D%E6%98%AF%E4%B8%80%E8%87%B4%E6%80%A7%E4%BA%8B%E5%8A%A1%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>缓冲是队列，容量满则停发射 store。这与 MSHR、保留站并列，又一项利用率缺口。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>TSO 一类模型允许 load 越过更早的 store（对不同地址），正是因为有这条缓冲；同地址仍要转发或停，否则连单线程 ISA 都错。弱序还允许更多重排，栅栏则抽干缓冲。模型课再收；本课只把硬件对象备好。</p><p>推测 load 若绕过了一条后来发现同地址的 store，必须取消 load 及其年轻指令。这与分支误预测同一套 ROB 冲刷。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入多线程共享同一缓冲，不把写结合缓冲当成第三种主结构。也不讨论非对齐 load 跨两条 store 的拼接细节。SMT 会让多条逻辑线程抢同一套访存队列——下一课。</p><p>后课默认：同核 load 能看见尚未提交到 cache 的年长 store。用多份硬件线程填空档是下一课 SMT。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>store 缓冲托住未对外的写；同地址 load 必须绕过。</li><li>地址未知则等或预测，错了冲刷 ROB。</li><li>SMT 用多线程共享这些队列，是下一课。</li><li>出处：Hennessy and Patterson, <em>CA:AQA</em> 访存序与 store buffer。</li></ul>',9))])}const b=s(h,[["render",E]]);export{C as __pageData,b as default};
